CREATE TABLE IF NOT EXISTS customers(id BIGINT PRIMARY KEY, username VARCHAR(80) UNIQUE NOT NULL, password_hash VARCHAR(300) NOT NULL, role VARCHAR(20) NOT NULL);
CREATE TABLE IF NOT EXISTS auth_sessions(token_hash VARCHAR(64) PRIMARY KEY, user_id BIGINT NOT NULL, expires_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS products(id BIGINT PRIMARY KEY, title VARCHAR(200) NOT NULL, category VARCHAR(80), description VARCHAR(2000), price DECIMAL(12,2) NOT NULL, stock INT NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS cart(user_id BIGINT NOT NULL, product_id BIGINT NOT NULL, quantity INT NOT NULL, PRIMARY KEY(user_id,product_id));
CREATE TABLE IF NOT EXISTS orders(id VARCHAR(80) PRIMARY KEY, user_id BIGINT NOT NULL, amount DECIMAL(12,2) NOT NULL, status VARCHAR(30) NOT NULL, address VARCHAR(300) NOT NULL, created_at BIGINT NOT NULL, request_key VARCHAR(100) NOT NULL, fingerprint VARCHAR(64) NOT NULL, UNIQUE(user_id,request_key));
CREATE TABLE IF NOT EXISTS order_items(order_id VARCHAR(80) NOT NULL, product_id BIGINT NOT NULL, title VARCHAR(200) NOT NULL, price DECIMAL(12,2) NOT NULL, quantity INT NOT NULL, PRIMARY KEY(order_id,product_id));
CREATE TABLE IF NOT EXISTS refunds(id VARCHAR(80) PRIMARY KEY, order_id VARCHAR(80) UNIQUE NOT NULL, user_id BIGINT NOT NULL, amount DECIMAL(12,2) NOT NULL, reason VARCHAR(500) NOT NULL, status VARCHAR(30) NOT NULL, created_at BIGINT NOT NULL, request_key VARCHAR(100) NOT NULL, review_note VARCHAR(500));
CREATE TABLE IF NOT EXISTS audit_log(id VARCHAR(80) PRIMARY KEY, user_id BIGINT NOT NULL, action VARCHAR(80) NOT NULL, target_id VARCHAR(80) NOT NULL, created_at BIGINT NOT NULL);
